// TypeScript Version: 4.1

/// <reference types="@stdlib/types"/>

import { Collection } from '@stdlib/types/array';

/**
* Interface describing `normalize`.
*/
interface Normalize {
	/**
	* Returns a normal number `y` and exponent `exp` satisfying \\(x = y \cdot 2^\mathrm{exp}\\).
	*
	* @param x - half-precision floating-point number
	* @returns output array
	*
	* @example
	* var toFloat16 = require( '@stdlib/number/float64/base/to-float16' );
	*
	* var v = normalize( toFloat16( 1.401e-6 ) );
	* // returns [ 0.00146484375, -10 ]
	*
	* @example
	* var v = normalize( 0.0 );
	* // returns [ 0.0, 0 ]
	*
	* @example
	* var PINF = require( '@stdlib/constants/float16/pinf' );
	*
	* var v = normalize( PINF );
	* // returns [ +Infinity, 0 ]
	*
	* @example
	* var NINF = require( '@stdlib/constants/float16/ninf' );
	*
	* var v = normalize( NINF );
	* // returns [ -Infinity, 0 ]
	*
	* @example
	* var v = normalize( NaN );
	* // returns [ NaN, 0 ]
	*/
	( x: number ): Array<number>;

	/**
	* Returns a normal number `y` and exponent `exp` satisfying \\(x = y \cdot 2^\mathrm{exp}\\) and assigns results to a provided output array.
	*
	* @param x - half-precision floating-point number
	* @param out - output array
	* @param stride - output array stride
	* @param offset - output array index offset
	* @returns output array
	*
	* @example
	* var Float16Array = require( '@stdlib/array/float16' );
	* var toFloat16 = require( '@stdlib/number/float64/base/to-float16' );
	*
	* var out = new Float16Array( 2 );
	*
	* var v = normalize.assign( toFloat16( 1.401e-6 ), out, 1, 0 );
	* // returns <Float16Array>[ 0.00146484375, -10 ]
	*
	* var bool = ( v === out );
	* // returns true
	*/
	assign<T = unknown>( x: number, out: Collection<T>, stride: number, offset: number ): Collection<T | number>;
}

/**
* Returns a normal number `y` and exponent `exp` satisfying \\(x = y \cdot 2^\mathrm{exp}\\).
*
* @param x - half-precision floating-point number
* @returns output array
*
* @example
* var toFloat16 = require( '@stdlib/number/float64/base/to-float16' );
*
* var v = normalize( toFloat16( 1.401e-6 ) );
* // returns [ 0.00146484375, -10 ]
*
* @example
* var v = normalize( 0.0 );
* // returns [ 0.0, 0 ]
*
* @example
* var PINF = require( '@stdlib/constants/float16/pinf' );
*
* var v = normalize( PINF );
* // returns [ +Infinity, 0 ]
*
* @example
* var NINF = require( '@stdlib/constants/float16/ninf' );
*
* var v = normalize( NINF );
* // returns [ -Infinity, 0 ]
*
* @example
* var v = normalize( NaN );
* // returns [ NaN, 0 ]
*/
declare var normalize: Normalize;


// EXPORTS //

export = normalize;
